'use strict';
const $ = id => document.getElementById(id);
document.querySelectorAll('[data-panel]').forEach(button=>button.onclick=()=>{
  document.body.dataset.mobilePanel=button.dataset.panel;
  document.querySelectorAll('[data-panel]').forEach(other=>other.setAttribute('aria-pressed',other===button));
  window.scrollTo({top:0,behavior:'instant'});
});
const filters = [
  {name:'Original',value:'none'}, {name:'Vintage',value:'sepia(.4) saturate(.8) contrast(.92)'},
  {name:'B&W',value:'grayscale(1)'}, {name:'Warm',value:'sepia(.25) saturate(1.3)'},
  {name:'Dreamy',value:'saturate(.65) contrast(.85) brightness(1.1)'}, {name:'Cool',value:'hue-rotate(20deg) saturate(.75)'}
];
const colors = [{name:'Vanilla',value:'#faf7ed'},{name:'Sage',value:'#dce3cf'},{name:'Rose',value:'#ead1ce'},{name:'Butter',value:'#f1e2af'},{name:'Sky',value:'#d2e0e4'},{name:'Lilac',value:'#ded6e8'},{name:'Midnight',value:'#363b34'}];
let state = {layout:'strip',filter:0,color:0,sticker:'',mirror:true,sound:false};
let stream = null, facing = 'user', uploaded = null, moments = [], busy = false, generation = 0, selectedMoment = null, toastTimer;
function toast(message) { $('toast').textContent=message; $('toast').hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('toast').hidden=true,4200); }
function filterValue() {return `${filters[state.filter].value==='none'?'':filters[state.filter].value} brightness(${$('brightness').value}%) contrast(${$('contrast').value}%)`.trim();}
function updatePreview(){ $('video').style.filter=filterValue(); $('uploadPreview').style.filter=filterValue(); $('demoArt').style.filter=filterValue(); if(selectedMoment && $('resultDialog').open) renderMoment(selectedMoment,$('resultCanvas')); }
filters.forEach((filter,index)=>{ const b=document.createElement('button');b.className='filter'+(index===0?' active':'');b.setAttribute('aria-pressed',index===0); const thumb=document.createElement('div');thumb.className='filter-thumb';thumb.style.filter=filter.value;b.append(thumb,document.createTextNode(filter.name));b.onclick=()=>{state.filter=index;document.querySelectorAll('.filter').forEach((el,i)=>{el.classList.toggle('active',i===index);el.setAttribute('aria-pressed',i===index);});updatePreview();};$('filters').append(b); });
colors.forEach((color,index)=>{const b=document.createElement('button');b.className='swatch'+(index===0?' active':'');b.style.setProperty('--swatch',color.value);b.style.setProperty('--tick',index===6?'#fff':'#69775a');b.setAttribute('aria-label',color.name+' frame');b.setAttribute('aria-pressed',index===0);b.onclick=()=>{state.color=index;$('colorName').textContent=color.name;document.querySelectorAll('.swatch').forEach((el,i)=>{el.classList.toggle('active',i===index);el.setAttribute('aria-pressed',i===index);});updatePreview();};$('swatches').append(b);});
document.querySelectorAll('.layout').forEach(b=>b.onclick=()=>{state.layout=b.dataset.layout;document.querySelectorAll('.layout').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b);});const count=state.layout==='single'?1:4;$('layoutCount').textContent=count+' photo'+(count===1?'':'s');$('captureText').textContent=count===1?'Take a photo':'Take 4 photos';$('boothNote').textContent=count===1?'One pose. One lovely little moment.':'Four poses. One lovely '+(state.layout==='grid'?'photo grid.':'photo strip.');updatePreview();});
document.querySelectorAll('[data-sticker]').forEach(b=>{b.setAttribute('aria-pressed',b.classList.contains('active'));b.onclick=()=>{state.sticker=b.dataset.sticker;document.querySelectorAll('[data-sticker]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b);});updatePreview();};});
['brightness','contrast','caption'].forEach(id=>$(id).addEventListener('input',updatePreview));
$('resetBtn').onclick=()=>{document.querySelector('[data-layout="strip"]').click();document.querySelector('.filter').click();document.querySelector('.swatch').click();document.querySelector('[data-sticker=""]').click();$('brightness').value=100;$('contrast').value=100;$('caption').value='';$('timer').value='3';$('format').value='png';updatePreview();toast('A fresh start. Your moments are still here.');};
function stopCamera(){generation++;if(stream) stream.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;$('video').hidden=true;$('cameraLabel').textContent='● CAMERA OFF';$('cameraLabel').classList.remove('on');$('stopBtn').hidden=true;busy=false;$('captureBtn').disabled=false;$('countdown').hidden=true;if(!uploaded){$('welcome').hidden=false;$('demoArt').hidden=false;}}
const stop=document.createElement('button');stop.id='stopBtn';stop.className='control';stop.textContent='Stop camera';stop.hidden=true;stop.onclick=()=>{stopCamera();toast('Camera off. Your photos stay in this tab.');};$('camera-controls');document.querySelector('.camera-controls').insertBefore(stop,$('soundBtn'));
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('Camera needs HTTPS or localhost and a supported browser. You can still upload photos.');return false;}const request=++generation;$('enableBtn').disabled=true;$('enableBtn').textContent='Opening camera…';try{const next=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:960}}});if(request!==generation){next.getTracks().forEach(t=>t.stop());return false;}if(stream) stream.getTracks().forEach(t=>t.stop());stream=next;uploaded=null;$('uploadPreview').hidden=true;$('video').srcObject=stream;$('video').hidden=false;$('video').classList.toggle('mirrored',state.mirror);await $('video').play();if(request!==generation)return false;$('welcome').hidden=true;$('demoArt').hidden=true;$('cameraLabel').textContent='● CAMERA ON';$('cameraLabel').classList.add('on');$('stopBtn').hidden=false;updatePreview();return true;}catch(error){toast(error.name==='NotAllowedError'?'Camera permission was declined. Allow it in browser settings, or upload a photo.':error.name==='NotFoundError'?'No camera found. Try uploading your favorite photos.':'Camera unavailable. Close other camera apps, or upload a photo.');return false;}finally{$('enableBtn').disabled=false;$('enableBtn').textContent='Enable camera ↗';}}
$('enableBtn').onclick=startCamera;
$('mirrorBtn').onclick=()=>{state.mirror=!state.mirror;$('mirrorBtn').classList.toggle('active',state.mirror);$('mirrorBtn').setAttribute('aria-pressed',state.mirror);$('video').classList.toggle('mirrored',state.mirror);};
$('switchBtn').onclick=async()=>{if(busy)return;if(!stream){toast('Enable your camera first.');return;}facing=facing==='user'?'environment':'user';stopCamera();await startCamera();};
$('soundBtn').onclick=()=>{state.sound=!state.sound;$('soundBtn').classList.toggle('active',state.sound);$('soundBtn').setAttribute('aria-pressed',state.sound);toast(state.sound?'Shutter sound on.':'Shutter sound off.');};
function shutterSound(){if(!state.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;const ctx=new AC(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=650;gain.gain.setValueAtTime(.07,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.09);osc.start();osc.stop(ctx.currentTime+.1);osc.onended=()=>ctx.close();}catch{}}
function drawCover(ctx,image,x,y,w,h){const iw=image.videoWidth||image.naturalWidth||image.width,ih=image.videoHeight||image.naturalHeight||image.height;const scale=Math.max(w/iw,h/ih);ctx.drawImage(image,(w-iw*scale)/2+x,(h-ih*scale)/2+y,iw*scale,ih*scale);}
function snapshot(){const c=document.createElement('canvas');c.width=1000;c.height=750;const ctx=c.getContext('2d');if(state.mirror){ctx.translate(c.width,0);ctx.scale(-1,1);}drawCover(ctx,$('video'),0,0,c.width,c.height);return c;}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function capture(){if(busy)return;if(!stream&&!uploaded){await startCamera();return;}if(uploaded){addMoment([uploaded]);return;}if(!$('video').videoWidth){toast('Camera is warming up. Try again in a moment.');return;}busy=true;$('captureBtn').disabled=true;const token=generation,photos=[],total=state.layout==='single'?1:4,delay=Number($('timer').value);try{for(let shot=0;shot<total;shot++){for(let n=delay;n>0;n--){if(token!==generation)return;$('countdown').textContent=n;$('countdown').hidden=false;$('captureText').textContent=`Pose ${shot+1} of ${total}`;await pause(1000);}if(token!==generation)return;$('countdown').hidden=true;photos.push(snapshot());shutterSound();$('flash').classList.remove('flash');void $('flash').offsetWidth;$('flash').classList.add('flash');if(shot<total-1)await pause(650);}addMoment(photos);}finally{busy=false;$('captureBtn').disabled=false;$('countdown').hidden=true;$('captureText').textContent=state.layout==='single'?'Take a photo':'Take 4 photos';}}
$('captureBtn').onclick=capture;
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();capture();}});
$('uploadBtn').onclick=()=>{if(!busy)$('fileInput').click();};
$('fileInput').onchange=async e=>{const files=Array.from(e.target.files);if(!files.length)return;const images=[];for(const file of files.slice(0,4)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024){toast('Choose a JPG, PNG, or WebP under 20 MB.');continue;}const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const c=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(image.width,image.height));c.width=Math.round(image.width*ratio);c.height=Math.round(image.height*ratio);c.getContext('2d').drawImage(image,0,0,c.width,c.height);images.push(c);}catch{toast('That image could not be opened. Try another photo.');}finally{URL.revokeObjectURL(url);}}e.target.value='';if(images.length){stopCamera();uploaded=images[0];$('uploadPreview').src=uploaded.toDataURL('image/jpeg',.9);$('uploadPreview').hidden=false;$('welcome').hidden=true;$('demoArt').hidden=true;$('cameraLabel').textContent='● LOCAL PHOTO';updatePreview();addMoment(images);if(images.length<4&&state.layout!=='single')toast('Photo added. Empty slots repeat your photos. Choose Solo shot for one.');}};
function renderMoment(moment,canvas){const count=state.layout==='single'?1:4,columns=state.layout==='grid'?2:1,rows=count/columns,pad=36,gap=22,w=state.layout==='strip'?600:state.layout==='grid'?1000:850,photoW=(w-pad*2-gap*(columns-1))/columns,photoH=photoW*.75,footer=100;canvas.width=w;canvas.height=pad*2+rows*photoH+gap*(rows-1)+footer;const ctx=canvas.getContext('2d');ctx.fillStyle=colors[state.color].value;ctx.fillRect(0,0,w,canvas.height);for(let i=0;i<count;i++){ctx.save();const x=pad+(i%columns)*(photoW+gap),y=pad+Math.floor(i/columns)*(photoH+gap);ctx.beginPath();ctx.rect(x,y,photoW,photoH);ctx.clip();ctx.filter=filterValue();drawCover(ctx,moment.photos[i%moment.photos.length],x,y,photoW,photoH);ctx.restore();}const dark=state.color===6;ctx.fillStyle=dark?'#faf7ed':'#4d6041';ctx.textAlign='center';ctx.font=`italic ${Math.round(w/26)}px Georgia`;const caption=$('caption').value.trim()||'a little moment, a lot of joy';let fontSize=Math.round(w/26);while(ctx.measureText(caption).width>w-pad*3&&fontSize>12){ctx.font=`italic ${--fontSize}px Georgia`;}ctx.fillText(caption,w/2,canvas.height-65);ctx.font=`${Math.round(w/65)}px Arial`;ctx.fillText('LITTLE MOMENTS  ·  '+moment.date,w/2,canvas.height-31);if(state.sticker){ctx.font=`${w/12}px Georgia`;ctx.fillStyle=state.sticker==='♥'?'#cc7e69':dark?'#e1cc90':'#8a966c';ctx.save();ctx.translate(w-pad-8,canvas.height-footer-12);ctx.rotate(.15);ctx.fillText(state.sticker,0,0);ctx.restore();}}
function addMoment(photos){if(moments.length>=12){toast('Session full. Download or remove a moment to make room.');return;}const moment={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),photos,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})};moments.push(moment);const canvas=document.createElement('canvas');renderMoment(moment,canvas);moment.thumbnail=canvas.toDataURL('image/jpeg',.85);renderGallery();openMoment(moment);}
function openMoment(moment){selectedMoment=moment;renderMoment(moment,$('resultCanvas'));$('resultDialog').showModal();}
function renderGallery(){$('momentCount').textContent=moments.length;$('gallery').replaceChildren();if(!moments.length){const el=document.createElement('div');el.className='empty-gallery';const icon=document.createElement('span');icon.className='empty-icon';icon.textContent='▧';const p=document.createElement('p');p.textContent='Your next favorite memory goes here.';const hint=document.createElement('span');hint.textContent='Take some photos to get started ✧';el.append(icon,p,hint);$('gallery').append(el);return;}moments.forEach((moment,index)=>{const card=document.createElement('div');card.className='moment';const image=document.createElement('img');image.src=moment.thumbnail;image.alt=`Photo moment ${index+1}`;const actions=document.createElement('div');actions.className='moment-actions';const edit=document.createElement('button');edit.textContent='Edit & save ↗';edit.onclick=()=>openMoment(moment);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`Delete moment ${index+1}`);remove.onclick=()=>{moments=moments.filter(m=>m!==moment);renderGallery();toast('Moment removed from this session.');};actions.append(edit,remove);card.append(image,actions);$('gallery').append(card);});}
$('downloadBtn').onclick=()=>{if(!selectedMoment)return;const canvas=$('resultCanvas');renderMoment(selectedMoment,canvas);const format=$('format').value;canvas.toBlob(blob=>{if(!blob){toast('Download failed. Try PNG format.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`little-moments-${Date.now()}.${format==='jpeg'?'jpg':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Saved to your device. Keep the good times.');},'image/'+format,.95);};
$('clearBtn').onclick=()=>{if(!moments.length&&!uploaded&&!stream){toast('Your session is already empty.');return;}showInfo('Clear this session?','<p>This turns off your camera and removes all photos from this tab. Download your favorites first. Files already downloaded stay on your device.</p><button id="confirmClear" class="primary">Clear photos & stop camera</button>');$('confirmClear').onclick=()=>{stopCamera();moments=[];uploaded=null;selectedMoment=null;$('uploadPreview').removeAttribute('src');$('uploadPreview').hidden=true;$('welcome').hidden=false;$('demoArt').hidden=false;renderGallery();$('infoDialog').close();toast('Session cleared. A clean slate.');};};
function showInfo(title,content){$('dialogContent').innerHTML='<h2>'+title+'</h2>'+content;$('infoDialog').showModal();}
$('privacyBtn').onclick=()=>showInfo('Your memories. Your business.','<p>Your camera feed and photos are processed entirely on your device. This booth has no backend, analytics, cookies, or photo uploads. It makes no network requests for photo processing.</p><p>Photos are held in this tab’s memory and disappear when you clear the session or close the tab. Downloads stay on your device. Imported image metadata is not copied into exported photos.</p><p>Camera access only starts when you enable it. Use <strong>Stop camera</strong> to revoke this session’s access. Hosting providers still receive normal page requests when you visit.</p>');
$('howBtn').onclick=()=>showInfo('A moment in three little steps.','<ol><li><strong>Get ready.</strong> Enable your camera, or use the upload button to choose up to four local photos.</li><li><strong>Make it yours.</strong> Pick a layout, filter, frame, caption, and sticker. Set your timer and strike a pose. Press Space to capture.</li><li><strong>Keep the magic.</strong> Preview your moment and download it as PNG or JPEG. Reopen any moment to change its style.</li></ol><p>Stay in this tab until you save your favorites. Your session is temporary.</p>');
document.querySelectorAll('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('resultDialog').addEventListener('close',()=>{if(selectedMoment){selectedMoment.thumbnail=$('resultCanvas').toDataURL('image/jpeg',.85);renderGallery();}selectedMoment=null;});
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('viewfinder').requestFullscreen)await $('viewfinder').requestFullscreen();else toast('Fullscreen is not supported by this browser.');}catch{toast('Fullscreen is not available.');}};
window.addEventListener('pagehide',stopCamera);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&stream)stopCamera();});
